from pathlib import Path
import re

P=Path('index.html');s=P.read_text(encoding='utf-8')
css='''
/* FUTURE_PRICE_ACTION_V6 */
.fpa-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:9px;margin-bottom:10px}.fpa-card{background:rgba(16,26,37,.96);border:1px solid var(--line);border-radius:14px;padding:12px}.fpa-card.pass{border-color:rgba(91,211,154,.5)}.fpa-card.fail{border-color:rgba(239,190,104,.35)}.fpa-path{font-size:18px;font-weight:950;margin:4px 0}.fpa-price{font-size:23px;font-weight:950;margin:4px 0}.fpa-scen{font-size:10px;color:var(--muted);line-height:1.5}.fpa-metrics{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-top:7px}.fpa-metric{background:#0c1621;border:1px solid #27394b;border-radius:8px;padding:6px}.fpa-metric span{display:block;font-size:8px;color:var(--muted);text-transform:uppercase}.fpa-metric b{display:block;margin-top:2px;font-size:11px}.fpa-forward{margin-top:9px;padding-top:9px;border-top:1px solid var(--line);display:flex;gap:7px;flex-wrap:wrap}.fpa-forward .chip{font-size:9px;border:1px solid #33495f;border-radius:999px;padding:4px 7px}@media(max-width:1080px){.fpa-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:700px){.fpa-grid{grid-template-columns:1fr}}
'''
if '/* FUTURE_PRICE_ACTION_V6 */' not in s:s=s.replace('</style>',css+'</style>')

js=r'''
/* FUTURE_PRICE_ACTION_V6_JS */
function fpaTone(path){return path==='UP'?'good':path==='DOWN'?'bad':'neutral'}
function fpaCard(z){if(!z||Object.keys(z).length===0)return '<div class="fpa-card fail"><div class="label">Unavailable</div></div>';const pass=!!z.pass,status=z.status||(pass?'PASS':'FAIL'),sc=z.scenario_20_50_80||[],risk=z.risk_10_90||[];return `<div class="fpa-card ${pass?'pass':'fail'}"><div class="projection-status"><div class="label">${z.horizon||'—'}</div><span class="pass-pill ${pass?'pass':'fail'}">${status}</span></div><div class="fpa-path ${fpaTone(z.dominant_path)}">${z.dominant_path||'—'}</div><div class="fpa-price">${money(z.predicted_price)}</div><div class="small">UP ${pct(z.probability_up)} • DOWN ${pct(z.probability_down)} • ${z.current_regime||'regime n/a'}</div><div class="fpa-scen">20/50/80: ${money(sc[0])} / ${money(sc[1])} / ${money(sc[2])}<br>Risk 10–90: ${money(risk[0])} – ${money(risk[1])}</div><div class="fpa-metrics"><div class="fpa-metric"><span>OOS acc.</span><b>${pct(z.directional_accuracy)}</b></div><div class="fpa-metric"><span>Dir. edge</span><b class="${Number(z.directional_edge)>=0?'good':'bad'}">${pct(z.directional_edge)}</b></div><div class="fpa-metric"><span>MAE skill</span><b class="${Number(z.mae_skill_vs_baseline)>=0?'good':'bad'}">${pct(z.mae_skill_vs_baseline)}</b></div><div class="fpa-metric"><span>Tests</span><b>${z.walkforward_origins??'—'}</b></div><div class="fpa-metric"><span>Recent edge</span><b>${pct(z.recent_directional_edge)}</b></div><div class="fpa-metric"><span>60% band cov.</span><b>${pct(z.interval_60_coverage)}</b></div></div></div>`}
function fpaEdgeCard(label,price,pup,status){const pass=/PASS/i.test(String(status||''))&&!/FAIL/i.test(String(status||''));return `<div class="fpa-card ${pass?'pass':'fail'}"><div class="projection-status"><div class="label">${label}</div><span class="pass-pill ${pass?'pass':'fail'}">${status||'FAIL'}</span></div><div class="fpa-price">${money(price)}</div><div class="small">UP ${pct(pup)} • DOWN ${pct(Number.isFinite(Number(pup))?1-Number(pup):null)}</div><div class="fpa-scen">Reference horizon. Deeper audit remains in the 4H / macro panels below.</div></div>`}
function futurePriceActionHTML(v6,ledger,asset){if(!v6||v6.status!=='ok')return `<div class="section-title">Future Price Action V6</div><div class="card"><div class="small">V6 data unavailable: ${v6?.reason||'waiting for next model run'}</div></div>`;const by=Object.fromEntries((v6.horizons||[]).map(x=>[x.horizon,x])),p=v6.path_summary||{};const cards=[fpaEdgeCard('4 Hours',p['4H']?.price,p['4H']?.probability_up,p['4H']?.status),fpaCard(by['1 Day']),fpaCard(by['1 Week']),fpaCard(by['1 Month']),fpaEdgeCard('1 Year',p['1Y']?.price,p['1Y']?.probability_up,p['1Y']?.status)].join('');const fw=(ledger?.summary||[]).filter(x=>x.asset===asset);const chips=fw.length?fw.map(x=>`<span class="chip">${x.horizon}: ${x.resolved_forecasts} live • ${(x.forward_direction_accuracy*100).toFixed(1)}% dir • ${Number(x.forward_mae_pct).toFixed(2)}% MAE</span>`).join(''):'<span class="small">Forward ledger started; accuracy appears after forecasts mature.</span>';return `<div class="section-title">Future Price Action V6 <span class="section-kicker">regime-conditioned • prior-OOS weighting • conformal-style scenario bands</span></div><div class="fpa-grid">${cards}</div><div class="card"><div class="chart-title">Live Forward Validation</div><div class="small">Unlike the backtest, these forecasts are timestamped before outcomes exist and scored only after each horizon matures.</div><div class="fpa-forward">${chips}</div></div>`}
function futurePriceActionShell(){return '<div id="futurePriceActionV6"></div>'}
async function hydrateFuturePriceAction(asset){const bust='?ts='+Date.now(),safe=u=>fetch(u+bust,{cache:'no-store'}).then(r=>r.ok?r.json():null).catch(()=>null);const [v6,ledger]=await Promise.all([safe(`data/${asset}_future_price_action_v6.json`),safe('data/forward_validation_ledger.json')]);const el=document.getElementById('futurePriceActionV6');if(el)el.innerHTML=futurePriceActionHTML(v6,ledger,asset)}
'''
if '/* FUTURE_PRICE_ACTION_V6_JS */' not in s:s=s.replace('function tradingViewSection(asset)',js+'\nfunction tradingViewSection(asset)')

if '+futurePriceActionShell()+v4Panel' not in s:
    s=s.replace('+v4Panel(h4,hs,mp,macro)', '+futurePriceActionShell()+v4Panel(h4,hs,mp,macro)')
if 'hydrateFuturePriceAction(asset)' not in s.split('async function loadAsset',1)[1]:
    s=s.replace('drawChart(t||{},asset)}','drawChart(t||{},asset);hydrateFuturePriceAction(asset)}')
P.write_text(s,encoding='utf-8');print('Future Price Action V6 dashboard patched')
